import { COLUMN_PRIVILEGES_SQL } from './sql/column-privileges'
import { z } from 'zod'

const pgColumnPrivilegesZod = z.object({
  column_id: z.string().regex(/^\d+\.\d+$/),
  relation_schema: z.string(),
  relation_name: z.string(),
  column_name: z.string(),
  privileges: z.array(
    z.object({
      grantor: z.string(),
      grantee: z.string(),
      privilege_type: z.union([
        z.literal('SELECT'),
        z.literal('INSERT'),
        z.literal('UPDATE'),
        z.literal('REFERENCES'),
      ]),
      is_grantable: z.boolean(),
    })
  ),
})
const pgColumnPrivilegesArrayZod = z.array(pgColumnPrivilegesZod)

function list({ columnIds }: { columnIds?: string[] } = {}): {
  sql: string
  zod: typeof pgColumnPrivilegesArrayZod
} {
  let sql = `
with column_privileges as (${COLUMN_PRIVILEGES_SQL})
select *
from column_privileges
`
  if (columnIds && columnIds.length > 0) {
    sql += ` where column_id in (${columnIds.map(literal).join(',')})`
  }
  return {
    sql,
    zod: pgColumnPrivilegesArrayZod,
  }
}

type ColumnPrivilegesGrant = {
  columnId: string
  grantee: string
  privilegeType: 'ALL' | 'SELECT' | 'INSERT' | 'UPDATE' | 'REFERENCES'
  isGrantable?: boolean
}
function grant(grants: ColumnPrivilegesGrant[]): { sql: string } {
  const sql = `
do $$
begin
${grants
  .map(({ privilegeType, columnId, grantee, isGrantable }) => {
    const [relationId, columnNumber] = columnId.split('.')
    return `execute format(
  'grant ${privilegeType}(%I) on table %s to ${
    grantee.toLowerCase() === 'public' ? 'public' : ident(grantee)
  } ${isGrantable ? 'with grant option' : ''}',
  (select attname from pg_attribute where attrelid = ${literal(relationId)} and attnum = ${literal(columnNumber)}),
  ${literal(relationId)}::regclass
);`
  })
  .join('\n')}
end $$;
`
  return { sql }
}

type ColumnPrivilegesRevoke = {
  columnId: string
  grantee: string
  privilegeType: 'ALL' | 'SELECT' | 'INSERT' | 'UPDATE' | 'REFERENCES'
}
function revoke(revokes: ColumnPrivilegesRevoke[]): { sql: string } {
  const sql = `
do $$
begin
${revokes
  .map(({ privilegeType, columnId, grantee }) => {
    const [relationId, columnNumber] = columnId.split('.')
    return `execute format(
  'revoke ${privilegeType}(%I) on table %s from ${
    grantee.toLowerCase() === 'public' ? 'public' : ident(grantee)
  }',
  (select attname from pg_attribute where attrelid = ${literal(relationId)} and attnum = ${literal(columnNumber)}),
  ${literal(relationId)}::regclass
);`
  })
  .join('\n')}
end $$;
`
  return { sql }
}

export default {
  list,
  grant,
  revoke,
  zod: pgColumnPrivilegesZod,
}
